"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3608],{93822:e=>{e.exports=JSON.parse('{"functions":[{"name":"ownsSkin","desc":"Returns true if the player owns the given skin (an [ItemRecord] for it\\nexists in `profile.inventory`).","params":[{"name":"player","desc":"owner to check","lua_type":"Player"},{"name":"itemId","desc":"skin id","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":91,"path":"src/Server/Features/Shop/CosmeticService.luau"}},{"name":"markPurchased","desc":"Marks a skin as purchased by adding an [ItemRecord] for it to\\n`profile.inventory` and replicates to the client. No-ops (returns false)\\nif already owned.","params":[{"name":"player","desc":"owner","lua_type":"Player"},{"name":"itemId","desc":"skin id to record","lua_type":"string"}],"returns":[{"desc":"false when already owned or the inventory write failed","lua_type":"boolean"}],"function_type":"static","source":{"line":108,"path":"src/Server/Features/Shop/CosmeticService.luau"}},{"name":"giftSkin","desc":"Grants a skin to the player and equips it. Used for first-session\\nstarter gifts (see `Data/Cosmetics/Defaults.luau`) and any other\\nserver-side handout flow (rewards, codes, etc.). The holster refreshes\\nthrough `ProfileService.ItemEquipped`.\\n\\nIdempotent: a re-gift simply re-equips without erroring. Returns false if\\nthe itemId isn\'t a known skin.","params":[{"name":"player","desc":"recipient","lua_type":"Player"},{"name":"itemId","desc":"skin id, must exist in `Data/Cosmetics/Skins`","lua_type":"string"}],"returns":[{"desc":"false when the id is not a known skin","lua_type":"boolean"}],"function_type":"static","source":{"line":132,"path":"src/Server/Features/Shop/CosmeticService.luau"}},{"name":"applyToCharacter","desc":"Rebuilds every hip holster on the player\'s current character from their\\nequipped skins. Idempotent; bound to `CharacterAdded` by\\n[CosmeticService.init] so holsters survive respawns.","params":[{"name":"player","desc":"character owner","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":289,"path":"src/Server/Features/Shop/CosmeticService.luau"}},{"name":"init","desc":"Boots the service: holsters every player already in the server, rebuilds\\nthem on every spawn and on every skin equip, and hands out the default\\nweapon skins on [PlayerService.PlayerLoaded].","params":[],"returns":[],"function_type":"static","source":{"line":364,"path":"src/Server/Features/Shop/CosmeticService.luau"}}],"properties":[],"types":[],"name":"CosmeticService","desc":"CosmeticService \u2014 owns cosmetic ownership/gift/equip behaviour and the\\nalways-on hip holsters. Lives outside the legacy ItemProcessor pipeline\\n(which is being phased out).\\n\\nOwnership lives in `profile.inventory` \u2014 the same [ItemRecord] array every\\nother item type uses \u2014 checked via [InventoryUtil]; the equipped selection\\nlives at `inventory_equipped[<slot>]` and is written through\\n[ProfileService:equipItem].\\n\\nEvery character wears one holster per entry in `HOLSTERS`: the equipped\\nknife skin on the right hip and the equipped gun skin on the left hip,\\nresolved through `Gearkit.Config.resolveModel` so an unowned or missing\\nskin falls back to the base gear model. A holster turns invisible while\\nthat gear\'s Tool is in the character\'s hands.\\n\\nNote: `FeatureFlags.SaveInventory` is currently off, so purchased\\ncosmetics only persist across a rejoin once that flag is turned on.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":26,"path":"src/Server/Features/Shop/CosmeticService.luau"}}')}}]);